import React, { useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { courses } from '../data/courses';
import PaymentModal from '../components/PaymentModal';
import Navbar from '../components/Navbar';

const CourseDetails = () => {
  const { id } = useParams();
  const [selectedCourse, setSelectedCourse] = useState(null);
  const course = courses.find(c => c.id === parseInt(id));

  if (!course) {
    return (
      <div className="min-h-screen bg-[#0A0E1A] text-white">
        <Navbar />
        <div className="flex flex-col items-center justify-center py-32 gap-4">
          <p className="text-slate-500 text-sm">Cours introuvable.</p>
          <Link to="/catalog" className="text-blue-400 hover:text-blue-300 font-semibold text-sm">
            ← Retour au catalogue
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0A0E1A] text-white">
      <Navbar />

      <section className="max-w-3xl mx-auto px-6 py-16">
        <Link to="/catalog" className="text-xs font-semibold text-slate-500 hover:text-slate-300 transition-colors mb-6 inline-block">
          ← Catalogue
        </Link>

        <div className="flex items-center gap-3 mt-2 mb-4">
          <span className={`text-[11px] font-bold uppercase tracking-wide px-3 py-1 rounded-full ${
            course.isFree ? 'bg-emerald-500/10 text-emerald-400' : 'bg-blue-500/10 text-blue-400'
          }`}>
            {course.isFree ? 'Gratuit' : 'Premium'}
          </span>
        </div>

        <h1 className="text-3xl md:text-4xl font-extrabold mb-4 leading-tight">
          {course.title}
        </h1>
        <p className="text-slate-400 text-sm mb-10 max-w-xl leading-relaxed">{course.description}</p>

        <div className="space-y-2 mb-10">
          <h3 className="text-xs font-semibold uppercase text-slate-500 tracking-wide mb-3">Programme</h3>
          {course.lessons.map(lesson => (
            <div key={lesson.id} className="flex justify-between items-center bg-slate-900/60 border border-slate-800 rounded-lg p-4 hover:border-slate-700 transition-colors">
              <span className="text-sm text-slate-200">{lesson.title}</span>
              <span>{lesson.locked ? '🔒' : '✅'}</span>
            </div>
          ))}
        </div>

        <div className="flex items-center justify-between bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
          <div>
            <span className="text-[11px] text-slate-500 uppercase tracking-wide block mb-1">Tarif</span>
            <span className="text-xl font-bold text-blue-400">
              {course.isFree ? 'Gratuit' : `${course.price.toLocaleString()} FCFA`}
            </span>
          </div>
          <button
            onClick={() => setSelectedCourse(course)}
            className="bg-blue-600 hover:bg-blue-500 text-white font-semibold px-8 py-3 rounded-lg text-sm transition-colors"
          >
            {course.isFree ? 'Accéder au cours' : "Débloquer l'accès à vie"}
          </button>
        </div>
      </section>

      {selectedCourse && <PaymentModal course={selectedCourse} onClose={() => setSelectedCourse(null)} />}
    </div>
  );
};
export default CourseDetails;
